import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);
});

test('createInvoice with multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-06',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'STICKER', qty: 100 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[1].name, 'Sticker sheet');
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for malformed date', () => {
  const cases = ['2026-13-01', '2026/10/07', '07-10-2026', '2026-10-7', 'not-a-date', '', 123];
  for (const issueDate of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(r.ok, false, `should reject: ${issueDate}`);
    assert.equal(r.error, 'DATE_INVALID', `should reject: ${issueDate}`);
  }
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns NO_LINES for missing lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns QTY_INVALID for non-positive quantities', () => {
  const cases = [0, -1, -100, 1.5, 'five', undefined, null];
  for (const qty of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty }],
    });
    assert.equal(r.ok, false, `should reject qty: ${qty}`);
    assert.equal(r.error, 'QTY_INVALID', `should reject qty: ${qty}`);
  }
});

test('createInvoice returns UNKNOWN_SKU for invalid SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'INVALID-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice stops at first error in lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'INVALID', qty: 1 },
    ],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines array', () => {
  const input = [{ sku: 'DEV-HOUR', qty: 5 }];
  const originalLine = { ...input[0] };
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: input,
  });
  assert.deepEqual(input[0], originalLine);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 5, unitPrice: 9500 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal works with single unit', () => {
  const line = { qty: 1, unitPrice: 1000 };
  assert.equal(lineTotal(line), 1000);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 1000, unitPrice: 50 };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals calculates subtotal from all lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 3, unitPrice: 8500 },
      { qty: 100, unitPrice: 50 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500 + 25500 + 5000);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.total, 10000);
});

test('invoiceTotals with zero-price items', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000 },
      { qty: 10, unitPrice: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.total, 5000);
});

test('invoiceTotals returns new object (does not mutate)', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000 }],
  };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('addLine adds a new line to the end', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'STICKER', qty: 50 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'STICKER');
  assert.equal(r.value.lines[1].qty, 50);
});

test('addLine increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 8);
  assert.equal(r.value.lines[0].name, 'Development (hour)');
});

test('addLine validates qty', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'STICKER', qty: -1 });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = addLine(invoice, { sku: 'INVALID-SKU', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  invoice.status = 'sent';
  const r = addLine(invoice, { sku: 'STICKER', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the input invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const originalLineCount = invoice.lines.length;
  const originalQty = invoice.lines[0].qty;
  addLine(invoice, { sku: 'STICKER', qty: 10 });
  assert.equal(invoice.lines.length, originalLineCount);
  assert.equal(invoice.lines[0].qty, originalQty);
});

test('removeLine removes a line by SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 10 },
    ],
  });
  const invoice = invoiceResult.value;
  const r = removeLine(invoice, 'STICKER');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
});

test('removeLine returns LINE_NOT_FOUND if SKU not on invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = removeLine(invoice, 'INVALID-SKU');
  assert.deepEqual(r, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine returns NO_LINES if it would remove the last line', () => {
