  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  const expectedVat = (100000 - 10000) * 0.21;
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 100000 - 10000 + expectedVat);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 300000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 21000 + 9000);
  assert.equal(totals.total, 300000 + 30000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 100, unitPrice: 1000, discountPercent: 5, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 200000);
  assert.equal(totals.discount, 10000 + 5000);
  const vat1 = (100000 - 10000) * 0.21;
  const vat2 = (100000 - 5000) * 0.09;
  assert.equal(totals.vat, vat1 + vat2);
  assert.equal(totals.total, 200000 - 15000 + vat1 + vat2);
});

test('invoiceTotals with no discount, no VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 10000);
});

test('invoiceTotals clamps total to 0 if discount > subtotal', () => {
