test('issueInvoice assigns number and sets status to issued', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const r = issueInvoice(invoice, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0001');
  assert.equal(r.value.status, 'issued');
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.lines.length, 1);
});

test('issueInvoice uses next available number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0003');
});

test('issueInvoice restarts numbering for new year', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = invoiceResult.value;
  const existing = ['INV-2026-0001', 'INV-2026-0999'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2027-0001');
});

test('issueInvoice returns NOT_DRAFT for non-draft invoice', () => {
