  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice rejects discountPercent below 0', () => {
  const cases = [-0.01, -1, -100];
  for (const discountPercent of cases) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent }],
    });
    assert.equal(r.ok, false, `should reject: ${discountPercent}`);
    assert.equal(r.error, 'DISCOUNT_INVALID', `should reject: ${discountPercent}`);
  }
});

test('createInvoice rejects discountPercent above 100', () => {
