test('invoiceTotals returns discount field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 1000);
});

test('invoiceTotals calculates total as subtotal minus discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 9000);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 },
      { qty: 20, unitPrice: 500, discountPercent: 5, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000 + 10000);
  assert.equal(totals.discount, 1000 + 500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 20000 - 1500);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
