    lines: [{ qty: 5, unitPrice: 100, discountPercent: 100, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 500);
  assert.equal(totals.discount, 500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with no discounts still returns discount field', () => {
