test('invoiceTotals with tier discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 5, vatRate: 0 },
      { qty: 20, unitPrice: 500, discountPercent: 2.5, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000 + 10000);
  assert.equal(totals.discount, 500 + 250);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 20000 - 750);
});

test('lineVAT calculates VAT on line amount after discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const vat = lineVAT(line);
  const lineAmountAfterDiscount = 10000 - 1000;
  const expectedVat = lineAmountAfterDiscount * 0.21;
  assert.equal(vat, expectedVat);
});

test('lineVAT with 0% VAT rate', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 };
  const vat = lineVAT(line);
  assert.equal(vat, 0);
});

test('lineVAT with 9% VAT rate', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 9 };
  const vat = lineVAT(line);
  assert.equal(vat, 9000);
});

test('lineVAT with 21% VAT rate', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const vat = lineVAT(line);
  assert.equal(vat, 21000);
});

test('lineVAT rounds per line', () => {
  const line = { qty: 3, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  const vat = lineVAT(line);
  const amountAfterDiscount = 300;
  const calculatedVat = amountAfterDiscount * 0.21;
  assert.equal(calculatedVat, 63);
  assert.equal(vat, 63);
});

test('lineVAT with fractional result rounds correctly', () => {
  const line = { qty: 1, unitPrice: 333, discountPercent: 0, vatRate: 21 };
  const vat = lineVAT(line);
  const calculatedVat = 333 * 0.21;
  assert.equal(calculatedVat, 69.93);
  assert.equal(vat, 70);
});

test('lineVAT with discount reduces VAT base', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 50, vatRate: 21 };
  const vat = lineVAT(line);
  const amountAfterDiscount = 100000 - 50000;
  const expectedVat = amountAfterDiscount * 0.21;
  assert.equal(vat, expectedVat);
  assert.equal(vat, 10500);
});

test('invoiceTotals returns vat field', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 21000);
});

test('invoiceTotals calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  const expectedVat = (100000 - 10000) * 0.21;
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 100000 - 10000 + expectedVat);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 9 },
      { qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 300000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 21000 + 9000);
  assert.equal(totals.total, 300000 + 30000);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 100, unitPrice: 1000, discountPercent: 5, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 200000);
  assert.equal(totals.discount, 10000 + 5000);
  const vat1 = (100000 - 10000) * 0.21;
  const vat2 = (100000 - 5000) * 0.09;
  assert.equal(totals.vat, vat1 + vat2);
  assert.equal(totals.total, 200000 - 15000 + vat1 + vat2);
});

test('invoiceTotals with no discount, no VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 10000);
});

test('invoiceTotals clamps total to 0 if discount > subtotal', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals VAT is sum of rounded line VATs', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Vat = lineVAT(invoice.lines[0]);
  const line2Vat = lineVAT(invoice.lines[1]);
  const line3Vat = lineVAT(invoice.lines[2]);
  assert.equal(totals.vat, line1Vat + line2Vat + line3Vat);
  assert.equal(totals.vat, 63);
});

