import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text for display to customers.
 * @param {{ number?: string, customerName: string, lines: Array<{ name: string, qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // First line: invoice number or "DRAFT"
  lines.push(invoice.number || 'DRAFT');

  // Second line: customer name
  lines.push(invoice.customerName);

  // Line items
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineText = `  ${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    lines.push(lineText);
  }

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // Subtotal
  lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);

  // Discount (if any)
  if (totals.discount > 0) {
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  // VAT (if any)
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Total
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}
